/// The versions this board rolled back from or refused for good. FIFO: a fifth
/// evicts the oldest, because a version old enough to be fifth will never be
/// offered again (offers are strictly newer than what runs).
struct FailedList {
  char versions[kMaxFailed][kVersionCap] = {};
  uint8_t count = 0U;

  bool contains(const char* version) const;
  void add(const char* version);
};

